<?php $taxonomy=sanitize_key($attributes['taxonomy']??'discipline'); $terms=get_terms(array('taxonomy'=>$taxonomy,'hide_empty'=>true)); if(is_wp_error($terms))$terms=array(); ?><nav <?php echo get_block_wrapper_attributes(array('class'=>'wugweb-taxonomy-filter','aria-label'=>ucfirst($taxonomy).' filters')); ?>><a href="<?php echo esc_url(get_post_type_archive_link('case_study')); ?>">All</a><?php foreach($terms as $term): ?><a href="<?php echo esc_url(add_query_arg($taxonomy,$term->slug,get_post_type_archive_link('case_study'))); ?>"><?php echo esc_html($term->name); ?></a><?php endforeach; ?></nav>